style.css:
/* Google Y2K — Digital Dream */
:root {
  /* customize the colors here */
  --my-bg: #100d1c;
  --my-purple: #bd91ff;
  --my-pink: #ff9de2;
  --my-text: #f4edff;
  --my-muted: #b8accb;
}

/* overall background */
body {
  background: var(--my-bg) !important;
  color: var(--my-text) !important;
  font-family: "Trebuchet MS", sans-serif !important;
}

/* futuristic typography */
h1, h2, h3 {
  font-family: "Arial Black", sans-serif !important;
  font-weight: 900 !important;
  letter-spacing: -1.5px !important;
}

/* search result titles */
a h3 {
  font-family: "Courier New", monospace !important;
  font-weight: bold !important;
  letter-spacing: -0.5px !important;
}

/* descriptions */
p, span {
  line-height: 1.75 !important;
}

/* links */
a {
  color: var(--my-purple) !important;
}

/* search box */
textarea,
input {
  border-radius: 18px !important;
  font-family: "Courier New", monospace !important;
}

/* selection */
::selection {
  background: var(--my-pink) !important;
  color: #24102e !important;
}

/* scrollbar */
::-webkit-scrollbar {
  width: 8px !important;
}

::-webkit-scrollbar-thumb {
  background: linear-gradient(var(--my-purple), var(--my-pink)) !important;
  border-radius: 20px !important;
}
